INSERT INTO `components_admission_procedures_sections` VALUES (1,'GUIDELINES','Admission Procedures','Registration for Admission:','For admission into the School, parents are invited to register for a particular year of entry. Prospectus and Registration forms are made available starting from 1st November.','Admission Tests and Interviews:','Following registration, admission and aptitude tests are administered to prospective candidates on a particular date fixed for it. Upon evaluation by a panel, according to the clearly defined admission criteria, successful candidates will be admitted on payment of the admission fee and other charges as applicable.');
