INSERT INTO `components_clubs_club_items` VALUES (1,'stem-robotics','Robotics & STEM Innovators Club','STEM & Innovation','Wednesday & Saturday (2:30 PM - 4:00 PM)','Computer & Advanced STEM Innovation Lab','A hands-on technology ecosystem where students bring code to life. Learners explore algorithmic thinking with Scratch and Python, build autonomous robots with sensor kits, design 3D models, and experiment with IoT concepts.','bg-blue-50 text-blue-700 border-blue-200','from-blue-600 to-indigo-700','/images/gallery-science-lab.jpg'),(2,'eco-warriors','Eco Warriors & Green Nature Club','Social & Eco','Tuesday & Friday (3:00 PM - 4:30 PM)','Campus Botanical Garden & Eco Zone','Dedicated to environmental conservation on and off campus. Members cultivate the school herbal garden, monitor zero-waste initiatives, lead seed-ball dispersion drives, and participate in nature trails around Imphal Valley.','bg-emerald-50 text-emerald-700 border-emerald-200','from-emerald-600 to-teal-700','/images/about-campus.jpg'),(3,'literary-debate','Literary, Debate & Model UN Society','Literary & Debate','Monday & Thursday (2:45 PM - 4:15 PM)','School Audio-Visual Seminar Hall','The premier oratorical and writing forum at Kids\' Foundation. Students hone public speaking, master Oxford-style and parliamentary debating, simulate UN diplomatic councils, and author creative prose.','bg-purple-50 text-purple-700 border-purple-200','from-purple-600 to-indigo-800','/images/academic-senior-secondary.jpg'),(4,'creative-arts','Creative Fine Arts & Traditional Crafts Guild','Arts & Culture','Saturday (9:30 AM - 12:00 PM)','Art Studio & Crafts Workshop','A joyful, vibrant studio space where students experiment with diverse visual arts mediums. From watercolors and charcoal sketches to traditional Manipuri handloom pattern designing and clay sculpture, creativity knows no bounds.','bg-amber-50 text-amber-700 border-amber-200','from-amber-500 to-orange-600','/images/academic-primary.jpg'),(5,'music-performing-arts','Harmony Music & Performing Arts Troupe','Arts & Culture','Wednesday & Friday (3:00 PM - 4:30 PM)','Performing Arts Hall & Music Room','Combining musical rhythm, classical and contemporary dance, and theatrical drama. Students learn vocal pitch control, explore traditional Manipuri folk instruments (Pena, Pung) alongside modern keyboards and guitars.','bg-rose-50 text-rose-700 border-rose-200','from-rose-600 to-pink-700','/images/gallery-dance.jpg'),(6,'martial-arts-taekwondo','Tae-Kwon-Do & Martial Arts Academy','Sports & Wellness','Tuesday, Thursday & Saturday (6:30 AM - 7:45 AM)','School Martial Arts Arena / Multipurpose Court','A rigorous, discipline-centered martial arts program emphasizing self-defense, focus, balance, and athletic agility. Students prepare for belt grading ceremonies and state and national CBSE competitions.','bg-red-50 text-red-700 border-red-200','from-red-600 to-rose-700','/images/gallery-taekwondo.jpg'),(7,'chess-mind-sports','Chess & Mind Sports Society','Sports & Wellness','Monday & Wednesday (3:00 PM - 4:15 PM)','Indoor Mind Sports Arena','A quiet haven for deep tactical calculations and friendly rivalries. Students master chess openings, middlegame tactics, endgame techniques, and test their logical prowess with timed blitz matches and puzzle battles.','bg-slate-100 text-slate-800 border-slate-300','from-slate-700 to-slate-900','/images/gallery-exam-hall.jpg'),(8,'heritage-community','Young Heritage & Social Service Club','Social & Eco','Every 2nd & 4th Saturday (10:00 AM - 1:00 PM)','Social Sciences Center & Off-Campus Field Sites','Committed to preserving the rich historical heritage of Manipur while fostering empathy and civic service. Students organize visits to eldercare homes, run book-donation drives, and explore ancient cultural monuments.','bg-teal-50 text-teal-700 border-teal-200','from-teal-600 to-cyan-800','/images/gallery-school-group.jpg'),(10,'fffff','ffffff','Teachers Day','ff',NULL,'fffffffff',NULL,NULL,NULL);
/*!40000 ALTER TABLE `components_clubs_club_items` ENABLE KEYS */;
UNLOCK TABLES;

