INSERT INTO `components_events_event_items` VALUES (1,'event-d1','Annual Sports Day 2026','2026-11-15','Nov','15','2026','Students from all grades compete in track & field, team sports and relay races on our sprawling school grounds. Parents and guardians are warmly invited to cheer on our young athletes.','Sports','/images/academic-early-years.jpg','Students competing in sports day activities','8:00 AM - 4:00 PM','School Grounds, Kids\' Foundation','upcoming'),(2,'event-d2','Science & Innovation Fair','2026-11-22','Nov','22','2026','An exciting showcase of student-led science projects, experiments and innovations spanning robotics, environment science, chemistry and mathematics. Open to all parents and community members.','Academic','/images/gallery-science-lab.jpg','Students presenting science fair projects','9:00 AM - 3:00 PM','Science Block & Main Hall','upcoming'),(3,'event-d3','Christmas & Winter Concert','2026-12-05','Dec','05','2026','Join us for an evening of music, drama and cultural performances as our students celebrate the spirit of Christmas with carols, dances and theatrical presentations.','Cultural','/images/news-cultural-meet.jpg','Students performing cultural concert','5:00 PM - 8:00 PM','School Auditorium','upcoming'),(4,'event-d4','Annual Prize Distribution Ceremony','2026-12-18','Dec','18','2026','A prestigious ceremony recognising academic excellence, co-curricular achievements and outstanding contributions by students across all grades. Parents and dignitaries are invited to grace the event.','Ceremony','/images/news-scholarship.jpg','Prize distribution ceremony at Kids Foundation','10:00 AM - 1:00 PM','Main Auditorium','upcoming'),(5,'event-d5','Teachers\' Day Celebration','2026-09-05','Sep','05','2026','Students honoured their teachers with heartfelt performances, speeches and personal tributes as part of a touching celebration marking National Teachers\' Day.','School Events','/images/academic-primary.jpg','Teachers Day celebration at Kids Foundation','9:00 AM - 12:00 PM','School Auditorium','past'),(6,'event-d6','Gandhi Jayanti - Cleanliness Drive','2026-10-02','Oct','02','2026','Students and staff came together for a special cleanliness drive around the campus and neighbouring areas to commemorate Gandhi Jayanti and promote community responsibility.','Community','/images/academic-secondary.jpg','Students participating in cleanliness drive','8:00 AM - 10:00 AM','Campus & Surrounding Areas','past'),(7,'event-d7','Inter-School Debate Competition','2026-10-15','Oct','15','2026','Kids\' Foundation hosted an inter-school debate competition bringing together students from 12 schools across Imphal to debate on contemporary social and environmental issues.','Academic','/images/academic-senior-secondary.jpg','Students debating at inter-school competition','10:00 AM - 3:00 PM','Conference Hall','past'),(8,'event-d8','Taekwondo Belt Grading Ceremony','2026-10-28','Oct','28','2026','Students from our martial arts programme underwent formal belt grading assessment, demonstrating discipline, skill and perseverance in front of certified examiners and proud parents.','Sports','/images/gallery-taekwondo.jpg','Taekwondo belt grading at Kids Foundation','9:00 AM - 12:00 PM','Multi-Purpose Hall','past'),(9,'dkjldfj','Teachers Day','2026-11-07',NULL,NULL,NULL,'Students from our martial arts programme underwent formal belt grading assessment, demonstrating discipline, skill and perseverance in front of certified examiners and proud parents.','School Events',NULL,NULL,'10 am to 2 pm ','School ','upcoming');
