INSERT INTO `components_home_about_sections` VALUES (3,'WELCOME TO KIDS\' FOUNDATION','Learning that goes beyond the classroom.','At Kids\' Foundation, we believe education is about developing the whole child. Our learning environment encourages students to question, explore, collaborate and discover their own strengths.','From the early years through senior school, we create opportunities for children to grow intellectually, socially, physically and emotionally — building not only knowledge, but the confidence and curiosity to use it.'),(4,'WELCOME TO KIDS\' FOUNDATION','Learning that goes beyond the classroom.','At Kids\' Foundation, we believe education is about developing the whole child. Our learning environment encourages students to question, explore, collaborate and discover their own strengths.','From the early years through senior school, we create opportunities for children to grow intellectually, socially, physically and emotionally — building not only knowledge, but the confidence and curiosity to use it.');
