INSERT INTO `components_news_news_items` VALUES (1,'notice-final-exam-timetable-class-xi','TIME TABLE FOR FINAL EXAMINATION 2024–25 FOR CLASS XI',NULL,'2026-10-18','Academic & Exams',1,'Time_Table_Final_Exam_Class_XI.png','200 KB','IMAGE',NULL,'/images/news/time-table-class-xi.png',1,NULL),(2,'notice-2026-11-10','CBSE Mid-Term Examination Results & Report Card Distribution','Official declaration of mid-term assessment outcomes for Classes VI to XII with scheduled parent-teacher meeting slots.','2026-10-10','Academic & Exams',1,'CBSE_MidTerm_Results_Summary_2026-27.pdf','420 KB','PDF','[\"The Academic Assessment Council of Kids\' Foundation School has formally compiled and ratified the Mid-Term Examination results for the academic session 2026-27 across Middle, Secondary, and Senior Secondary stages (Classes VI through XII).\", \"Individual report cards, subject-wise mark rubrics, and formative learning observations will be distributed during the scheduled Parent-Teacher Meeting (PTM) on Saturday, November 18, 2026, from 8:30 AM to 1:00 PM. Parents and guardians must accompany their wards in complete school uniform.\", \"Subject-wise remedial clinic schedules and guidance sessions will also be provided during the meeting for students requiring reinforcement in mathematics, science, and languages.\"]',NULL,1,NULL),(3,'notice-2026-11-03','Admissions Open for Academic Session 2027-28 (Pre-Nursery to Class XI)','Registration process, prospectus availability, entrance evaluation guidelines, and timeline for prospective new admissions.','2026-10-03','Admissions',1,'Admission_Guidelines_Prospectus_2027-28.pdf','1.8 MB','PDF','[\"Online registration and in-person prospectus collection for the upcoming academic session 2027-28 commence on Monday, November 6, 2026, at the administrative block counter.\", \"Limited entry vacancies are available across Pre-Nursery, Nursery, Kindergarten, Primary (Classes I-V), Middle School (Classes VI-VIII), Secondary (Classes IX-X), and Senior Secondary streams (Science, Commerce, Arts).\", \"Parents are encouraged to review eligibility ages, required documentation, and entrance assessment schedules on the admissions portal.\"]',NULL,0,NULL),(4,'notice-2026-10-24','Annual Sports Meet & Inter-House Athletic Championships 2026','Schedule of field trials, track events, martial arts demonstrations, and march-past parade rehearsals.','2026-10-24','Events & Culture',1,'Annual_Sports_Meet_Event_Schedule_2026.pdf','650 KB','PDF','[\"The 19th Annual Sports Meet of Kids\' Foundation School will be celebrated from November 14 to November 16, 2026, on the main sports campus field.\", \"Events include sprint races, relays, long jump, shot put, taekwondo kata demonstrations, and the prestigious Inter-House March Past trophy.\", \"House captains and coaches will conduct preliminary heats daily after class hours. Attendance is mandatory for all registered athletes.\"]',NULL,0,NULL),(5,'notice-2026-10-14','State Level Science & Tinkering Exhibition 2026 - Outstanding Student Honours','Kids\' Foundation innovation team wins first prize in the Renewable Energy & Robotics category at the Regional Science Conclave.','2026-10-14','Achievements',0,NULL,NULL,NULL,'[\"We are immensely proud to announce that the four-member student engineering team from Class IX secured First Position at the Manipur State Inter-School Science Fair 2026.\", \"Their prototype \'Smart Solar Irrigation & Soil Moisture Sensor Grid\' was widely lauded by the judging panel from Manipur University and NIT Imphal.\", \"The team has been nominated to represent the state at the National Children\'s Science Congress later this winter.\"]',NULL,0,NULL),(6,'notice-2026-09-28','Revised School Timings & Winter Uniform Directive (w.e.f. October 15)','Notification on transition to winter session schedule, assembly timings, and prescribed blazer uniform codes.','2026-09-28','Circulars & Notices',1,'Winter_Session_Timings_Uniform_Notice_2026.pdf','310 KB','PDF','[\"In view of seasonal daylight adjustments and colder morning temperatures, school reporting time will shift to 8:45 AM starting Monday, October 15, 2026.\", \"Students must report in full winter uniform including navy blazer with school crest, formal tie, and sweater as prescribed in the handbook.\"]',NULL,0,NULL),(7,'ffff','ffff','dffffff','2026-10-25','Admissions',0,'ff','122mb','dsfdf','[\"djlskfdlsklfks\"]',NULL,1,NULL),(8,'120','new news',NULL,'2026-10-29','Circulars & Notices',1,NULL,'25mb',NULL,NULL,NULL,1,10);
/*!40000 ALTER TABLE `components_news_news_items` ENABLE KEYS */;
UNLOCK TABLES;

