INSERT INTO `components_publications_publication_cards` VALUES (1,'pub-budding-sprouts-2026','The Budding Sprouts - Annual School Magazine','Magazine & Newsletter','Vol. XIX, 2025-26','2026-01-15','2025-2026',72,'14.2 MB','PDF','English & Manipuri','The flagship annual publication of Kids\' Foundation School celebrating student creativity, original poetry, creative essays, artwork, faculty reflections, and school achievements across sports, academics, and performing arts.','[\"Founder\'s & Principal\'s Annual Keynote\", \"Student Literary Section: 40+ Original Poems & Short Stories\", \"Visual Arts Showcase: Paintings from Fine Arts Guild\", \"CBSE Board Achievers & Merit Roll of Honour\", \"Annual Sports & Cultural Meet Photo Journal\", \"Alumni Reflections & Faculty Contributions\"]','/images/news-cultural-meet.jpg','Kids_Foundation_The_Budding_Sprouts_2025_26.pdf','School Editorial Board & Literary Guild',1),(2,'pub-academic-handbook-2026-27','Curriculum & Academic Assessment Handbook','Academic Handbook','Session 2026-27','2026-02-01','2026-2027',48,'4.8 MB','PDF','English','Comprehensive guide to the academic curriculum, CBSE evaluation rubrics, exam schedules, grading frameworks, scholastic and co-scholastic learning standards for Pre-Nursery to Class XII.','[\"CBSE Affiliation Norms & Subject Blueprints\", \"Periodic Assessment & Term Examination Weightages\", \"Grading Scales and Continuous Comprehensive Evaluation (CCE)\", \"Science Laboratory Safety Directives\", \"Student Discipline & Attendance Protocols\"]','/images/gallery-exam-hall.jpg','Kids_Foundation_Academic_Handbook_2026_27.pdf','Academic Council & Curriculum Committee',0),(3,'pub-annual-report-2024-25','Annual Institutional Performance & Governance Report','Annual Report','Annual Review 2024-25','2025-12-10','2024-2025',56,'6.1 MB','PDF','English','Official institutional report detailing annual governance, infrastructure developments, CBSE Board examination results, teacher development programs, athletic achievements, and financial accountability.','[\"100% Pass Percentage in CBSE Class X Examinations\", \"New Senior Secondary STEM & Computer Lab Commissioning\", \"Faculty Continuous Professional Development (CPD) Hours\", \"Eco-Friendly Green Campus & Solar Infrastructure Audit\", \"Community Outreach & CSR Education Initiatives\"]','/images/campus-aerial.jpg','Kids_Foundation_Annual_Report_2024_25.pdf','Office of the Managing Committee',0),(4,'pub-student-parent-guide-2026','Parent & Student Code of Conduct & Welfare Guide','Parent & Student Guide','Edition 2026','2026-03-05','2026-2027',36,'3.4 MB','PDF','English','Essential orientation guide for parents and enrolled learners covering school ethos, digital discipline policies, health & safety standards, transport guidelines, and counseling support services.','[\"Anti-Bullying & Child Protection Protocols (POCSO Guidelines)\", \"Health, First-Aid & Emergency Response Protocols\", \"Parent-Teacher Engagement Calendar & Office Timings\", \"School Bus Safety Routes and Fleet Rules\"]','/images/gallery-school-group.jpg','Kids_Foundation_Parent_Student_Guide_2026.pdf','Student Welfare & Counseling Cell',0);
