INSERT INTO `components_shared_activity_items` VALUES (1,'YOGA','To help concentration and breathing. Yoga means union of body with spirit. Learning Yoga in early life will prove advantages for the child in later life.'),(2,'AEROBICS','To help the students to develop a liking for physical movements and rhythm. It also helps in the development of gross and fine motor skills through movements, music and dance.'),(3,'MARTIAL ARTS','Martial arts is a sports basically used for combat and for physical and spiritual development. It is also used for self-defence. Kids’ Foundation has a regular course of various martial arts like karate, taekwondo, judo etc.'),(4,'WATER-POOL','KIDS’ FOUNDATION has a pool for water games. The pool is constructed to fit their height and the level of water is kept very shallow. Pool games will help the child to overcome the fear of water and will also help in learning how to swim.'),(5,'FINE ARTS','Art teacher teaches innovative and creative thinking. It allows them to think of new ideas.'),(6,'PERFORMING ARTS','Performing arts such as Drama, Music and Dance encourages students to develop their artistic expressions.');
/*!40000 ALTER TABLE `components_shared_activity_items` ENABLE KEYS */;
UNLOCK TABLES;

