/*!40000 ALTER TABLE `components_shared_learning_stages` DISABLE KEYS */;
INSERT INTO `components_shared_learning_stages` VALUES (1,'foundational','Foundational','Nurturing wonder & play','[\"Every child is born a discoverer propelled by the instinctive need to know more. Kids’ Foundation early childhood is designed to encourage the natural curiosity and fearless sense of enquiry of children between the ages of 3 and 6. Our pre-primary learning curriculum and strategy is completely child centred and full of fun filled activities. On top of the usual curriculum.These activities are included so that children are exposed to an all-round development of their potentials. They are encouraged to be in sync with nature, we have included:\"]','[\"DANCES\", \"MUSIC\", \"YOGA\", \"AEROBICS\", \"STORY TELLING CLASSES\", \"BIRD FEEDING/ FISH FEEDING CLASSES\"]','Pre-primary students engaged in learning activities','PRE-NURSERY • NURSERY • LKG • UKG • AGES 3–5'),(2,'preparatory','Preparatory','Building core skills & discovery','[\"The freedom to question is the freedom to learn. Kids Foundation recognises the importance of preserving the innate curiosity of early childhood throughout primary years. The primary classes are introduced to self-study and individualised construction of knowledge. Students are exposed to the different modes of learning like group discussion, pair activities and brain storming. Technologies are incorporated into the teaching modes for elaboration of understanding and comprehension.\"]','[\"Experiential Learning\", \"Foundational Numeracy\", \"Creative Arts\"]','Primary students in classroom activities','CLASSES I – V • AGES 6–10'),(3,'secondary','Secondary','Fostering analytical thinking','[\"Education must be multi-dimensional because every child innately is. The middle years are a challenging time of transition for learners as they move from childhood to adolescence. This crucial period of personal, social, physical and intellectual growth is marked by uncertainty on one hand and increasing maturity on the other. In cognizance to the CBSE directives, KIDS’ FOUNDATION is delivering a holistic learning approach. Primary importance is given to DISCIPLINE, ATTENDANCE, SINCERITY, BEHAVIOUR, VALUES and other co-scholastic activities which will cater to the needs of the community and build wholesome personalities of students. Martial Arts, Arts and Crafts, and Elocution are given importance. For scholastic learning, quizzes and debates based on the curriculum and syllabus is organised. Project works and assignments are part and parcel of the learning tasks.\"]','[\"STEM Labs\", \"Critical Thinking\", \"Leadership & Sports\"]','Secondary students in focused learning environment','CLASSES VI – X • AGES 11–15'),(4,'middle school','Middle School','Expanding horizons & inquiry','[\"The Middle school strengthens conceptual understanding and independent thinking. Students explore diverse subjects, collaborate on projects, and develop problem-solving skills in a supportive environment.\"]','[\"Inquiry-Based Learning\", \"Collaboration\", \"Project Work\"]','Middle school students engaged in interactive learning','CLASSES VI – VIII • AGES 11–13');
/*!40000 ALTER TABLE `components_shared_learning_stages` ENABLE KEYS */;
UNLOCK TABLES;

