INSERT INTO `components_shared_text_items` VALUES (1,'mission','Our Mission','Widen the Child\'s opportunities for the highest level of cognitive, social, physical, emotional and aesthetic growth while cultivating multiple intelligence.'),(2,'philosophy','Our Philosophy','The World is getting smaller everyday with the technology and communication explosion. The paradigm shift from local to global is a continuous process of change and the need.'),(3,'vision','Our Vision','Shaping happy, life-long learners who will succeed in and contribute to the global community.');
