INSERT INTO `contact_pages` VALUES (1,'ohsg4l7s73ej20ghq5luxz0p','Contact Us','[\"Contact\"]',NULL,'GET IN TOUCH','We\'d love to hear from you','Whether you have questions about admissions, our curriculum, campus tours, or general queries, our friendly administrative team is here to assist you.','Send Us a Message','Have questions about admissions, campus tours, or anything else? We\'d love to hear from you.','Send Message','FIND US','Visit Our Campus','Airport Road, NH 150, Ghari, Imphal, Manipur 795001','https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d7244.770281699026!2d93.9014291!3d24.7776411!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3749261ea6480eaf%3A0xba24397b1a9bc2f6!2sKids%E2%80%99%20Foundation%20School%20%7C%20Manipur!5e0!3m2!1sen!2sin!4v1730000000000!5m2!1sen!2sin','https://www.google.com/maps/place/Kids%E2%80%99+Foundation+School+%7C+Manipur/@24.7764361,93.9105756,16z/data=!4m6!3m5!1s0x3749261ea6480eaf:0xba24397b1a9bc2f6!8m2!3d24.7764361!4d93.9105756!16s%2Fg%2F1hc2jgz_7','Kids’ Foundation School | Manipur Location','2026-10-28 13:59:47.374000','2026-10-28 16:13:13.385000','2026-10-28 16:13:13.349000',NULL,1,NULL);
