INSERT INTO `learning_pages` VALUES (1,'nhya4sz4msqdzyvfiqplnvt7','Learning','[\"Learning\"]','Building the right foundation through learning','OUR APPROACH','\nLearning\nWe aim to provide our students, who are confident in their academic success and are developing socially, physically and psychologically, with a happy and engaging learning environment that is structured, collaborative and purposeful. Kids’ Foundation is not about obtaining the best marks, but about getting students to be best they can be. We seek to develop students as individuals who achieve their full potential. Kids’ Foundation is committed on building a complete personality-a person with a strong moral backbone and integrity. Thus, a promise to give your child the right foundation. Our learning technique is based on constructivism. We believe that each individual child has the potential to construct their own knowledge.','2026-10-28 11:57:06.087000','2026-10-29 12:13:46.074000','2026-10-29 12:13:45.941000',NULL,1,NULL);
/*!40000 ALTER TABLE `learning_pages` ENABLE KEYS */;
