INSERT INTO `sports_and_arts_pages` VALUES (1,'pjjivw0lq0o455qbysmz6z3s','Sports & Arts','[\"About\", \"Sports & Arts\"]','SPORTS & ARTS','Sports & Arts','SPORTS AND SPORTSMANSHIP – we aim to encourage both in our students. As a part of our pursuit of truly holistic education, Kids’ Foundation offers an enjoyable balance between physical activity and learning. Physical Education (P.E.) at Kids’ Foundation is an integral part of our curricula.','[\"At our school, we pride ourselves on providing top-notch sports and arts facilities that cater to the diverse interests and talents of our students. Our sports facilities are designed to promote physical fitness, teamwork, and sportsmanship across various disciplines.\", \"In the realm of sports, we offer a wide range of options to suit every interest and skill level. Football enthusiasts can hone their skills on our well-maintained football field, while basketball lovers can enjoy competitive matches on our indoor and outdoor courts. For those who prefer indoor games, we have dedicated spaces for chess and carrom, fostering strategic thinking and friendly competition among students.\"]','2026-10-28 11:58:03.008000','2026-10-28 11:58:03.008000','2026-10-28 11:58:02.965000',NULL,NULL,NULL);
